import { useEffect, useState } from "react";

import SectionCard from "./SectionCard.jsx";

export default function LessonPlayer({ track }) {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    setIndex(0);
  }, [track?.id]);

  if (!track) {
    return (
      <SectionCard title="Lesson path">
        <div className="rounded-[2rem] border border-dashed border-white/15 p-8 text-center text-slate-400 light:border-slate-300 light:text-slate-600">
          Pick a tree topic to begin.
        </div>
      </SectionCard>
    );
  }

  const activeItem = track.sequence[index] || track.sequence[0];

  return (
    <SectionCard title={track.title} eyebrow="Structured learning path">
      <div className="grid gap-6 xl:grid-cols-[0.42fr,0.58fr]">
        <div className="space-y-3">
          {track.sequence.map((item, itemIndex) => (
            <button
              key={item.id}
              type="button"
              onClick={() => setIndex(itemIndex)}
              className={`w-full rounded-[1.5rem] border px-4 py-4 text-left transition ${
                itemIndex === index
                  ? "border-cyan-300/50 bg-cyan-400/10 text-cyan-50"
                  : "border-white/10 bg-white/5 text-slate-300 hover:bg-white/10 light:border-slate-200 light:bg-white light:text-slate-700"
              }`}
            >
              <p className="text-xs uppercase tracking-[0.24em] text-slate-400">{item.level}</p>
              <h3 className="mt-2 font-display text-lg font-semibold">{item.title}</h3>
              <p className="mt-2 text-sm leading-6">{item.summary}</p>
            </button>
          ))}
        </div>

        <div className="space-y-4">
          <div className="rounded-[2rem] border border-white/10 bg-white/5 p-5 light:border-slate-200 light:bg-white">
            <p className="text-xs font-semibold uppercase tracking-[0.24em] text-slate-400">
              Current topic
            </p>
            <h3 className="mt-3 font-display text-2xl font-bold text-white light:text-slate-900">
              {activeItem.title}
            </h3>
            <p className="mt-3 text-sm leading-7 text-slate-300 light:text-slate-700">
              {activeItem.body}
            </p>
          </div>

          {activeItem.imageUrl ? (
            <div className="overflow-hidden rounded-[2rem] border border-white/10 bg-slate-950/40 light:border-slate-200 light:bg-white">
              <img
                src={activeItem.imageUrl}
                alt={activeItem.title}
                className="h-auto w-full object-cover"
              />
            </div>
          ) : (
            <div className="rounded-[2rem] border border-dashed border-white/15 bg-slate-950/30 p-8 text-center text-sm text-slate-400 light:border-slate-300 light:bg-slate-100 light:text-slate-600">
              This step is concept-focused. Move through the sequence from basic to advanced.
            </div>
          )}

          <div className="rounded-[2rem] border border-white/10 bg-white/5 p-5 light:border-slate-200 light:bg-white">
            <p className="text-xs font-semibold uppercase tracking-[0.24em] text-slate-400">
              Progress
            </p>
            <p className="mt-3 text-sm text-slate-300 light:text-slate-700">
              Step {index + 1} of {track.sequence.length}: {activeItem.summary}
            </p>
          </div>
        </div>
      </div>
    </SectionCard>
  );
}
